using System;
using System.Collections.Generic;
using System.Globalization;
using System.Text.RegularExpressions;
using RTXMnesia.World;
using UnityEngine;

namespace RTXMnesia.Hpl
{
    /// <summary>
    /// An HPL2 .cfg file (config/game.cfg etc.): elements = sections, attributes = values, all kept as text
    /// and read with the same getters as cConfigFile (GetFloat("Player_Body", "Mass", 0) …).
    /// Generated by the importer into Assets/AmnesiaImported/Config (game data, never in git).
    /// </summary>
    public class HplConfig : ScriptableObject
    {
        [Serializable]
        public class Section
        {
            public string name;
            public List<HplVariable> values = new();
        }

        public string sourceFile;
        [TextArea] public string sourceXml;
        public List<Section> sections = new();

        Dictionary<string, Dictionary<string, string>> _lookup;

        public string GetString(string section, string name, string fallback = "") => Find(section, name) ?? fallback;

        public float GetFloat(string section, string name, float fallback = 0f)
        {
            string s = Find(section, name);
            return s != null && TryParseFloat(s, out float f) ? f : fallback;
        }

        public int GetInt(string section, string name, int fallback = 0) => Mathf.RoundToInt(GetFloat(section, name, fallback));

        public bool GetBool(string section, string name, bool fallback = false)
        {
            string s = Find(section, name);
            if (s == null) return fallback;
            s = s.Trim().ToLowerInvariant();
            return s == "true" || s == "1" || s == "yes";
        }

        public Vector2 GetVector2(string section, string name, Vector2 fallback = default)
        {
            float[] v = Floats(section, name);
            return v == null ? fallback : new Vector2(At(v, 0), At(v, 1));
        }

        public Vector3 GetVector3(string section, string name, Vector3 fallback = default)
        {
            float[] v = Floats(section, name);
            return v == null ? fallback : new Vector3(At(v, 0), At(v, 1), At(v, 2));
        }

        public Color GetColor(string section, string name, Color fallback = default)
        {
            float[] v = Floats(section, name);
            return v == null ? fallback : new Color(At(v, 0), At(v, 1), At(v, 2), v.Length > 3 ? v[3] : 1f);
        }

        /// <summary>Like atof in cString::ToFloat: the numeric prefix counts ("0.01f" → 0.01).</summary>
        public static bool TryParseFloat(string s, out float value)
        {
            var m = NumberPrefix.Match(s.Trim());
            value = 0f;
            return m.Success && float.TryParse(m.Value, NumberStyles.Float, CultureInfo.InvariantCulture, out value);
        }

        static readonly Regex NumberPrefix = new(@"^[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?");

        static float At(float[] v, int i) => i < v.Length ? v[i] : 0f;

        float[] Floats(string section, string name)
        {
            string s = Find(section, name);
            if (s == null) return null;
            var parts = s.Split(new[] { ' ', '\t', ',' }, StringSplitOptions.RemoveEmptyEntries);
            var result = new float[parts.Length];
            for (int i = 0; i < parts.Length; i++) TryParseFloat(parts[i], out result[i]);
            return result;
        }

        string Find(string section, string name)
        {
            if (_lookup == null)
            {
                _lookup = new Dictionary<string, Dictionary<string, string>>(StringComparer.OrdinalIgnoreCase);
                foreach (var sec in sections)
                {
                    if (!_lookup.TryGetValue(sec.name, out var values))
                        _lookup[sec.name] = values = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
                    foreach (var v in sec.values) values[v.name] = v.value;
                }
            }
            return _lookup.TryGetValue(section, out var sectionValues) && sectionValues.TryGetValue(name, out string value) ? value : null;
        }

        void OnValidate() => _lookup = null;
    }
}
